INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured")
SELECT '« Recruteur dans le foot : j’ai payé 3 000 euros pour un rêve sans débouché »', 'recruteur-dans-le-foot-j-ai-paye-3000-euros-pour-un-reve-sans-debouche', 'Il a 30 ans, il est passionné de foot et il a vu une publicité sur Facebook. Six mois et plus de 3 000 euros plus tard, il raconte à Passe D les dessous d’une formation de recruteur. Il a souhaité rester anonyme.', '<p><strong>Passe D : Pour commencer, présente-toi.</strong></p><p>Je préfère rester anonyme. J’ai 30 ans, et j’ai joué au foot dans des clubs amateurs.</p><p><strong>Qu’est-ce qui t’a donné envie de devenir recruteur ?</strong></p><p>L’amour du foot. On sait que c’est un sport où il y a beaucoup d’argent, et je savais que je ne pouvais pas réussir en tant que professionnel. Déjà parce que c’est trop tard, et aussi parce que je n’ai pas le niveau. Je voyais le métier de recruteur comme une opportunité. Après une publicité sur Facebook, je me suis dit : « C’est top. Tu regardes des matchs, tu es dans une structure professionnelle et tu seras proche de joueurs professionnels. » Je me disais que je vivrais ma passion à travers ce métier.</p><p><strong>Parle-nous de cette formation. Combien t’a-t-elle coûté, et que t’a-t-on promis ?</strong></p><p>Elle m’a coûté plus de 3 000 euros. Elle durait six mois, entre guillemets, mais en fait tu as deux semaines de théorie, et le reste du temps tu es avec un tuteur. On m’a promis d’être dans un club professionnel et d’avoir un suivi. En s’inscrivant à cette formation, on pense qu’on va élargir notre réseau et intégrer une structure pro si la formation se passe bien.</p><p><strong>Dans les faits, comment ça s’est passé ?</strong></p><p>J’ai eu un bon groupe. Moi, j’ai eu un club professionnel, mais certains du groupe non. Le tuteur, oui, on peut dire ça comme ça : il m’a accompagné à un ou deux matchs au début, et après tu es autonome. Tu apprends des choses, mais pas comme je le pensais.</p><p><strong>À quoi ressemble ton quotidien de recruteur ? Tu es payé, tu as un contrat ?</strong></p><p>Je n’ai rien du tout. C’était un stage non rémunéré. Tu n’as aucun contact direct avec le club, seulement avec ton tuteur. Je pense même que le club ne doit pas être au courant de ta présence.</p><p>Tu as une liste de matchs à aller voir, ou c’est le tuteur qui t’y envoie. Tu vois des matchs le mercredi, le samedi et le dimanche, et plusieurs matchs par jour. En moyenne, le mercredi c’est un ou deux, ça dépend vraiment, et le week-end trois ou quatre. Il y a aussi les tournois que tu enchaînes, et les détections.</p><p><strong>Qui paie les déplacements ? Et que deviennent tes rapports ?</strong></p><p>Tout est à ma charge. Tu te dis que c’est un stage : quand tu rêves de réussir et d’intégrer le club, tu acceptes tout.</p><p>Après chaque match, je rédige mes rapports. Je ne sais pas ce qu’il en fait. Je pense qu’ils sont regardés, sans plus. Je détectais des joueurs, et le tuteur me disait « Ouais, OK », mais il n’a jamais bougé pour ces joueurs. Aujourd’hui, certains de ces joueurs sont dans de plus gros clubs ou avec de gros agents.</p><p><strong>Avec le recul, que ressens-tu par rapport à cette formation ?</strong></p><p>Un sentiment mitigé. Je me dis qu’en fait, un recruteur, c’est toi et ta perception. Du coup, c’est dur d’évaluer qu’un recruteur est meilleur qu’un autre. Ta réputation dépend de ta capacité à attirer les joueurs, mais plus ton club est gros, moins c’est dur.</p><p>J’ai quand même appris des choses, bien sûr, et j’ai même progressé dans ma vision. Je regrette juste d’avoir mis autant d’argent dans une formation où il n’y a pas de débouché.</p><p><strong>Que dirais-tu à un jeune passionné qui voit la même pub demain ?</strong></p><p>Ça dépend de plein de facteurs, mais je lui dirais de réfléchir à deux fois avant de payer autant. C’est un métier où il n’y a pas de débouchés, où le cercle est très, très restreint, et où ceux qui sont en place tiennent tellement à leur place qu’ils restent de nombreuses années sans bouger, malgré une paie très faible. Il y a beaucoup plus de recruteurs que de demande. Donc je lui conseillerais d’accéder à ce métier autrement, même si c’est un super métier.</p><p><em>Vous avez vécu une expérience similaire ? Écrivez-nous.</em></p><p>— Passe D</p>', 'entretien', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'metiers-du-football'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  now(), now(), 4, false
ON CONFLICT ("slug") DO NOTHING;
